// bytes from "a client": they name AuditHook, not Authorization
val hostile = serialize(AuditHook("chosen by whoever wrote the bytes"))

// no filter: readObject runs AuditHook's code, then the cast fails
try {
    ObjectInputStream(ByteArrayInputStream(hostile)).use { it.readObject() } as Authorization
} catch (e: ClassCastException) {
    println("  ClassCastException, but only after readObject had run")
}

// an allow-list: exact names, a depth limit, and !* for everything else
val filter = ObjectInputFilter.Config.createFilter(
    "maxdepth=5;sfz.enc.l01.demo.Authorization;java.util.Arrays\$ArrayList;java.lang.String;!*"
)
try {
    ObjectInputStream(ByteArrayInputStream(hostile)).use {
        it.setObjectInputFilter(filter)
        it.readObject() as Authorization
    }
} catch (e: InvalidClassException) {
    println("  ${e.javaClass.simpleName}: ${e.message}")
} catch (e: ClassCastException) {
    println("  the filter let AuditHook through: ClassCastException after readObject ran")
}

val mapper = jacksonObjectMapper()
val json = """{"paymentId":1849204436731904017,"amountMinor":4000}"""
val node = mapper.readTree(json).get("paymentId")
println("read as a Long:    ${node.longValue()}")
// a double has 53 bits for the digits; JavaScript's JSON.parse does exactly this
println("read as a double:  ${BigDecimal(node.asDouble()).toPlainString()}")

val twoTo53 = 1L shl 53
for (id in listOf(twoTo53 - 1, twoTo53, twoTo53 + 1, twoTo53 + 2)) {
    println("%d -> as a double -> %s".format(id, BigDecimal(id.toDouble()).toPlainString()))
}

