fun readAuthorization(bytes: ByteArray): Authorization {
    val filter = ObjectInputFilter.Config.createFilter(
        "maxdepth=5;sfz.enc.l01.Authorization;java.util.ArrayList;java.lang.String;java.lang.Object;!*"
    )
    return ObjectInputStream(ByteArrayInputStream(bytes)).use { input ->
        input.setObjectInputFilter(filter)   // before the first readObject
        input.readObject() as Authorization  // the cast is a type check, not a defence
    }
}
